 <div className="finance-view-switch"><button className={tab==="overview"?"selected":""} onClick={()=>setTab("overview")}>{(englishUI?"This month":"이번 달")}</button><button className={tab==="analysis"?"selected":""} onClick={()=>setTab("analysis")}>{(englishUI?"Annual view":"1년 보기")}</button></div>
 {error&&<div className="finance-alert error">{error}</div>}{notice&&<div className="finance-alert success">{notice}</div>}{!supabase&&<div className="finance-alert">{(englishUI?"Configure Supabase environment variables to access live financial data.":"Supabase 환경변수를 설정하면 실제 재정 데이터를 사용할 수 있습니다.")}</div>}
 {tab==="overview"&&<>
 <section className="finance-cashbook-head"><div><span className="eyebrow">CASHBOOK</span><h3>{(englishUI?"Monthly transactions":"이번 달 돈 기록")}</h3><p>{(englishUI?"Record income and expenses and immediately view this month's totals.":"들어온 돈과 나간 돈을 적고, 이번 달 합계를 바로 봅니다.")}</p></div><label>{(englishUI?"Select month":"볼 달")}<input type="month" value={cashbookMonth} onChange={e=>setCashbookMonth(e.target.value)}/></label></section>
 <section className="finance-total-balance"><div><span>{(englishUI?"Current balance":"지금 가진 돈")}</span><strong>{loading?"…":money(cashbook.cashBalance)} <small>MMK</small></strong><p>{(englishUI?"Combined total of recorded cash, bank and points balances.":"저장된 현금·은행·포인트 기록을 모두 더한 금액입니다.")}</p></div><span>{(englishUI?"All transactions":"모든 기록")}</span></section>
 <section className="finance-quick-entry"><div><strong>{(englishUI?"Transactions":"거래 기록")}</strong><span>{(englishUI?"Enter only the category, amount and description without complex accounting entries.":"어려운 회계 입력 없이 항목, 금액, 내용만 입력합니다.")}</span></div><div><button className="finance-primary" onClick={()=>openQuick("income")}>{(englishUI?"＋ Income":"＋ 수입")}</button><button onClick={()=>openQuick("expense")}>{(englishUI?"＋ Expense":"＋ 지출")}</button></div></section>
 {showQuick&&<section className="finance-form finance-quick-form"><h4>{quickEditingId?"기록 수정":quickKind==="income"?"수입 기록":"지출 기록"}</h4><div className="finance-form-grid"><FormField label={(englishUI?"Date":"날짜")}><input type="date" value={quickDate} onChange={e=>setQuickDate(e.target.value)}/></FormField><FormField label={(englishUI?"Fund":"기금")}><select value={quickFund} onChange={e=>setQuickFund(e.target.value)}>{funds.map(f=><option key={f.id} value={f.id}>{fundName(f)}</option>)}</select></FormField><FormField label={quickKind==="income"?"수입 항목":"지출 항목"}><select value={quickAccount} onChange={e=>setQuickAccount(e.target.value)}>{accounts.filter(a=>a.account_type===quickKind&&!["4000","4100","5100","5200"].includes(a.code)).map(a=><option key={a.id} value={a.id}>{accountName(a)}</option>)}</select></FormField><FormField label={(englishUI?"Cash & bank":"현금·은행")}><select value={quickCashAccount} onChange={e=>setQuickCashAccount(e.target.value)}>{accounts.filter(a=>a.account_type==="asset").map(a=><option key={a.id} value={a.id}>{accountName(a)}</option>)}</select></FormField><FormField label={(englishUI?"Content":"내용")} className="wide"><input value={quickDescription} onChange={e=>setQuickDescription(e.target.value)} placeholder={quickKind==="income"?"예: 후원금 입금":"예: 식수 구입"}/></FormField><FormField label={(englishUI?"Amount (MMK)":"금액 (MMK)")}><input type="number" min="1" value={quickAmount} onChange={e=>setQuickAmount(e.target.value)} placeholder="0"/></FormField></div><div className="finance-form-actions"><button onClick={()=>{setShowQuick(false);setQuickEditingId("");}}>{(englishUI?"Cancel":"취소")}</button><button className="finance-primary" disabled={saving||!quickAccount||!quickCashAccount||!quickFund||!quickDescription.trim()||Number(quickAmount)<=0} onClick={()=>void submitQuick()}>{saving?"저장 중…":quickEditingId?"수정 저장":"장부에 저장"}</button></div></section>}
 <div className="finance-metrics"><article><span>{(englishUI?"Income":"들어온 돈")}</span><strong>{loading?"…":money(cashbook.income)}</strong><small>{cashbookMonth} · MMK</small></article><article><span>{(englishUI?"Recurring expenses":"매달 나가는 돈")}</span><strong>{loading?"…":money(cashbook.fixed)}</strong><small>{(englishUI?"Recurring costs":"정기 비용")}</small></article><article><span>{(englishUI?"Occasional expenses":"그때그때 쓴 돈")}</span><strong>{loading?"…":money(cashbook.variable)}</strong><small>{(englishUI?"Supplies, repairs and events":"물품·수리·행사")}</small></article><article><span>{(englishUI?"Remaining monthly balance":"이번 달 남은 돈")}</span><strong>{loading?"…":money(cashbook.income-cashbook.fixed-cashbook.variable)}</strong><small>{(englishUI?"Income − expenses":"들어온 돈 − 나간 돈")}</small></article></div>
 <section className="finance-panel finance-ledger-panel"><div className="finance-panel-head"><div><h3>{cashbookMonth} 상세 내역</h3><p>{(englishUI?"Review records by date, as in a spreadsheet ledger.":"엑셀 장부처럼 날짜별로 확인합니다.")}</p></div><strong>{monthlyEntries.length}{(englishUI?"":"건")}</strong></div><div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>{(englishUI?"Date":"날짜")}</th><th>{(englishUI?"Category":"구분")}</th><th>{(englishUI?"Item":"항목")}</th><th>{(englishUI?"Content":"내용")}</th><th>{(englishUI?"Amount":"금액")}</th><th>{(englishUI?"Management":"관리")}</th></tr></thead><tbody>{monthlyEntries.map(entry=><tr key={entry.id}><td>{entry.date}</td><td><span className={"finance-status "+entry.type}>{entry.type==="income"?"수입":"지출"}</span></td><td>{entry.account}</td><td>{entry.description}</td><td>{money(entry.amount)}</td><td><div className="finance-actions"><button onClick={()=>editQuick(entry.entry)}>{(englishUI?"Edit":"수정")}</button><button onClick={()=>void deleteQuick(entry.entry)}>{(englishUI?"Delete":"삭제")}</button></div></td></tr>)}</tbody></table>{!loading&&!monthlyEntries.length&&<div className="empty-state"><strong>{(englishUI?"No transactions recorded this month":"이 달에 기록된 거래가 없습니다")}</strong></div>}</div></section>
 <section className="finance-panel"><div className="finance-panel-head"><div><h3>{(englishUI?"Summary by category":"항목별 요약")}</h3><p>{(englishUI?"Review the sources of income and uses of expenses.":"수입과 지출이 어디에 사용됐는지 확인합니다.")}</p></div></div><div className="finance-cashbook-columns"><div><h4>{(englishUI?"Income":"수입")}</h4>{cashbook.rows.filter(x=>x.account.account_type==="income").map(x=><p key={x.account.id}><span>{accountName(x.account)}</span><strong>{money(x.amount)}</strong></p>)}{!cashbook.rows.some(x=>x.account.account_type==="income")&&<small>{(englishUI?"No income recorded.":"등록된 수입이 없습니다.")}</small>}</div><div><h4>{(englishUI?"Expense":"지출")}</h4>{cashbook.rows.filter(x=>x.account.account_type==="expense").map(x=><p key={x.account.id}><span>{accountName(x.account)}</span><strong>{money(x.amount)}</strong></p>)}{!cashbook.rows.some(x=>x.account.account_type==="expense")&&<small>{(englishUI?"No expenses recorded.":"등록된 지출이 없습니다.")}</small>}</div></div></section>
 </>}
 {tab==="analysis"&&<section className="finance-analysis"><section className="finance-cashbook-head"><div><span className="eyebrow">YEARLY MONEY</span><h3>{(englishUI?"Annual finances":"1년 돈 보기")}</h3><p>{(englishUI?"Select a year to view monthly income and expenses.":"연도를 고르면, 달마다 들어온 돈과 나간 돈을 볼 수 있습니다.")}</p></div><label>{(englishUI?"Select year":"볼 연도")}<select value={analysisYear} onChange={event=>setAnalysisYear(event.target.value)}>{availableAnalysisYears.map(year=><option key={year} value={year}>{year}{(englishUI?"":"년")}</option>)}</select></label></section><div className="finance-metrics"><article><span>{(englishUI?"Annual income":"1년 들어온 돈")}</span><strong>{loading?"…":money(annualTotals.income)}</strong><small>{analysisYear}{(englishUI?" · MMK":"년 · MMK")}</small></article><article><span>{(englishUI?"Annual recurring expenses":"1년 매달 나가는 돈")}</span><strong>{loading?"…":money(annualTotals.fixed)}</strong><small>{(englishUI?"Recurring costs":"정기 비용")}</small></article><article><span>{(englishUI?"Annual occasional expenses":"1년 그때그때 쓴 돈")}</span><strong>{loading?"…":money(annualTotals.variable)}</strong><small>{(englishUI?"Occasional expenses":"필요할 때 쓴 비용")}</small></article><article><span>{(englishUI?"Annual remaining balance":"1년 남은 돈")}</span><strong>{loading?"…":money(annualTotals.income-annualTotals.fixed-annualTotals.variable)}</strong><small>{(englishUI?"Income − expenses":"들어온 돈 − 나간 돈")}</small></article></div><section className="finance-panel finance-analysis-table"><div className="finance-panel-head"><div><h3>{(englishUI?"Monthly breakdown":"달마다 보기")}</h3><p>{(englishUI?"Months showing zero have no recorded transactions.":"0인 달은 아직 적은 기록이 없습니다.")}</p></div></div><div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>{(englishUI?"Mon":"월")}</th><th>{(englishUI?"Income":"들어온 돈")}</th><th>{(englishUI?"Recurring expenses":"매달 나가는 돈")}</th><th>{(englishUI?"Occasional expenses":"그때그때 쓴 돈")}</th><th>{(englishUI?"Remaining balance":"남은 돈")}</th></tr></thead><tbody>{annualAnalysis.months.map(row=><tr key={row.month}><td>{row.month}</td><td>{money(row.income)}</td><td>{money(row.fixed)}</td><td>{money(row.variable)}</td><td className={row.income-row.fixed-row.variable>=0?"finance-positive":"finance-negative"}>{money(row.income-row.fixed-row.variable)}</td></tr>)}</tbody></table></div></section><section className="finance-panel finance-fixed-monthly"><div className="finance-panel-head"><div><h3>{(englishUI?"Recurring expense categories":"매달 나가는 돈 항목")}</h3><p>{(englishUI?"Review monthly spending by category.":"어떤 항목에 얼마씩 나갔는지 달마다 확인합니다.")}</p></div></div><div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>{(englishUI?"Item":"항목")}</th>{annualAnalysis.months.map(row=><th key={row.month}>{Number(row.month.slice(5,7))}{(englishUI?"":"월")}</th>)}<th>{(englishUI?"Annual total":"1년 합계")}</th></tr></thead><tbody>{annualAnalysis.fixedMonthlyRows.map(row=><tr key={row.account.id}><td>{accountName(row.account)}</td>{row.amounts.map((amount,index)=><td key={index}>{money(amount)}</td>)}<td><strong>{money(row.total)}</strong></td></tr>)}</tbody></table>{!annualAnalysis.fixedMonthlyRows.length&&<div className="empty-state"><strong>{(englishUI?"No recurring expenses recorded":"매달 나가는 돈 기록이 없습니다")}</strong></div>}</div></section><section className="finance-cashbook-columns finance-panel"><div><h4>{(englishUI?"Income categories":"들어온 돈 항목")}</h4>{annualAnalysis.incomeRows.map(row=><p key={row.account.id}><span>{accountName(row.account)}</span><strong>{money(row.amount)}</strong></p>)}{!annualAnalysis.incomeRows.length&&<small>{(englishUI?"No financial records.":"등록된 돈이 없습니다.")}</small>}</div><div><h4>{(englishUI?"Total recurring expenses":"매달 나가는 돈 항목 합계")}</h4>{annualAnalysis.fixedRows.map(row=><p key={row.account.id}><span>{accountName(row.account)}</span><strong>{money(row.amount)}</strong></p>)}{!annualAnalysis.fixedRows.length&&<small>{(englishUI?"No records.":"등록된 기록이 없습니다.")}</small>}</div></section></section>}
 {tab==="transactions"&&<section className="finance-panel"><div className="finance-panel-head"><div><h3>{(englishUI?"Income and expense transactions":"수입·지출 거래")}</h3><p>{(englishUI?"Register double-entry accounting vouchers and view them by fund.":"복식부기 전표를 등록하고 기금별로 조회합니다.")}</p></div><button className="finance-primary" onClick={()=>{setEditingEntryId("");setDate(today());setDescription("");setReference("");setLines([{account_id:"",description:"",debit:"",credit:""},{account_id:"",description:"",debit:"",credit:""}]);setShowEntry(x=>!x);}}>{(englishUI?"＋ Register transaction":"＋ 거래 등록")}</button></div><div className="finance-filter"><select value={filterFund} onChange={e=>setFilterFund(e.target.value)}><option value="all">{(englishUI?"All funds":"모든 기금")}</option>{funds.map(f=><option key={f.id} value={f.id}>{fundName(f)}</option>)}</select><button onClick={()=>void load()}>{(englishUI?"Refresh":"새로고침")}</button></div>
 {showEntry&&<div className="finance-form"><h4>{editingEntryId?"임시 전표 수정":"새 회계 전표"}</h4><div className="finance-form-grid"><FormField label={(englishUI?"Transaction date":"거래일")}><input type="date" value={date} onChange={e=>setDate(e.target.value)}/></FormField><FormField label={(englishUI?"Fund":"기금")}><select value={fundId} onChange={e=>setFundId(e.target.value)}>{funds.map(f=><option key={f.id} value={f.id}>{fundName(f)}</option>)}</select></FormField><FormField label={(englishUI?"Transaction description":"거래 내용")} className="wide"><input value={description} onChange={e=>setDescription(e.target.value)} placeholder={(englishUI?"e.g. Donation received, textbooks purchased":"예: 후원금 수령, 교재 구입")}/></FormField><FormField label={(englishUI?"Reference number":"참조번호")}><input value={reference} onChange={e=>setReference(e.target.value)}/></FormField></div><div className="finance-lines-head"><strong>{(englishUI?"Journal entries":"분개 항목")}</strong><span>{(englishUI?"Total debits must equal total credits.":"차변과 대변 합계가 일치해야 합니다.")}</span></div>{lines.map((l,i)=><div className="finance-line" key={i}><select value={l.account_id} onChange={e=>updateLine(i,"account_id",e.target.value)}><option value="">{(englishUI?"Select account":"계정과목 선택")}</option>{accounts.map(a=><option key={a.id} value={a.id}>{a.code} · {accountName(a)}</option>)}</select><input value={l.description} onChange={e=>updateLine(i,"description",e.target.value)} placeholder={(englishUI?"Item description":"항목 설명")}/><input type="number" min="0" value={l.debit} onChange={e=>updateLine(i,"debit",e.target.value)} placeholder={(englishUI?"Debit":"차변")}/><input type="number" min="0" value={l.credit} onChange={e=>updateLine(i,"credit",e.target.value)} placeholder={(englishUI?"Credit":"대변")}/></div>)}<button className="finance-add-line" onClick={addLine}>{(englishUI?"＋ Add journal entry":"＋ 분개 항목 추가")}</button><div className="finance-balance"><span>{(englishUI?"Debit ":"차변 ")}<b>{money(debit)}</b></span><span>{(englishUI?"Credit ":"대변 ")}<b>{money(credit)}</b></span><strong className={debit===credit&&debit>0?"balanced":"unbalanced"}>{debit===credit&&debit>0?"차대변 일치":"차대변 불일치"}</strong></div><div className="finance-form-actions"><button onClick={()=>{setShowEntry(false);setEditingEntryId("");}}>{(englishUI?"Cancel":"취소")}</button><button disabled={saving} onClick={()=>void submitEntry(false)}>{editingEntryId?"수정 저장":"임시 저장"}</button><button className="finance-primary" disabled={saving||debit<=0||debit!==credit||!description.trim()||!fundId} onClick={()=>void submitEntry(true)}>{editingEntryId?"수정 후 결재 요청":"저장 후 결재 요청"}</button></div></div>}
 <div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>{(englishUI?"Voucher":"전표")}</th><th>{(englishUI?"Transaction date":"거래일")}</th><th>{(englishUI?"Content":"내용")}</th><th>{(englishUI?"Fund":"기금")}</th><th>{(englishUI?"Status":"상태")}</th><th>{(englishUI?"Amount":"금액")}</th><th>{(englishUI?"Management":"관리")}</th></tr></thead><tbody>{filtered.map(e=><tr key={e.id}><td>#{e.entry_no}</td><td>{e.entry_date}</td><td>{e.description}</td><td>{fundName(funds.find(f=>f.id===e.fund_id))}</td><td><span className={"finance-status "+e.status}>{status(e.status)}</span></td><td>{money((e.journal_lines??[]).reduce((s,l)=>s+Number(l.debit),0))}</td><td>{["draft","rejected"].includes(e.status)?<div className="finance-actions"><button onClick={()=>editEntry(e)}>{(englishUI?"Edit":"수정")}</button><button onClick={()=>void deleteEntry(e)}>{(englishUI?"Delete":"삭제")}</button></div>:"—"}</td></tr>)}</tbody></table>{!loading&&!filtered.length&&<div className="empty-state"><strong>{(englishUI?"No transactions registered":"등록된 거래가 없습니다")}</strong><span>{(englishUI?"Register your first transaction.":"첫 거래를 등록해 보세요.")}</span></div>}</div></section>}
 {tab==="budgets"&&<section className="finance-panel"><div className="finance-panel-head"><div><h3>{(englishUI?"Annual budget management":"연간 예산 관리")}</h3><p>{(englishUI?"Prepare expense budgets by fund and compare them with actual expenditure.":"기금별 지출 예산을 편성하고 실제 집행액과 비교합니다.")}</p></div><button className="finance-primary" onClick={()=>{setEditingBudgetId("");setBudgetYear(String(new Date().getFullYear()));setBudgetTitle("");setBudgetLines([{account_id:"",planned_amount:"",notes:""}]);setShowBudget(x=>!x);}}>{(englishUI?"＋ Create budget":"＋ 예산 편성")}</button></div>
 {showBudget&&<div className="finance-form"><h4>{editingBudgetId?"임시 예산안 수정":"새 예산안"}</h4><div className="finance-form-grid"><FormField label={(englishUI?"Fiscal year":"회계연도")}><input type="number" min="2000" max="2200" value={budgetYear} onChange={e=>setBudgetYear(e.target.value)}/></FormField><FormField label={(englishUI?"Fund":"기금")}><select value={budgetFund} onChange={e=>setBudgetFund(e.target.value)}>{funds.map(f=><option key={f.id} value={f.id}>{fundName(f)}</option>)}</select></FormField><FormField label={(englishUI?"Budget name":"예산안 이름")} className="wide"><input value={budgetTitle} onChange={e=>setBudgetTitle(e.target.value)} placeholder={(englishUI?"e.g. 2027 general operating budget":"예: 2027 일반 운영 예산")}/></FormField></div><div className="finance-lines-head"><strong>{(englishUI?"Budget item":"예산 항목")}</strong><span>{(englishUI?"Only expense accounts can be selected.":"지출 계정과목만 선택할 수 있습니다.")}</span></div>{budgetLines.map((l,i)=><div className="finance-budget-line" key={i}><select value={l.account_id} onChange={e=>setBudgetLines(old=>old.map((x,n)=>n===i?{...x,account_id:e.target.value}:x))}><option value="">{(englishUI?"Select expense account":"지출 계정 선택")}</option>{accounts.filter(a=>a.account_type==="expense").map(a=><option key={a.id} value={a.id}>{a.code} · {accountName(a)}</option>)}</select><input type="number" min="1" value={l.planned_amount} onChange={e=>setBudgetLines(old=>old.map((x,n)=>n===i?{...x,planned_amount:e.target.value}:x))} placeholder={(englishUI?"Budget amount (MMK)":"예산 금액 (MMK)")}/><input value={l.notes} onChange={e=>setBudgetLines(old=>old.map((x,n)=>n===i?{...x,notes:e.target.value}:x))} placeholder={(englishUI?"Notes":"비고")}/></div>)}<button className="finance-add-line" onClick={()=>setBudgetLines(old=>[...old,{account_id:"",planned_amount:"",notes:""}])}>{(englishUI?"＋ Add budget item":"＋ 예산 항목 추가")}</button><div className="finance-form-actions"><button onClick={()=>{setShowBudget(false);setEditingBudgetId("");}}>{(englishUI?"Cancel":"취소")}</button><button disabled={saving} onClick={()=>void createBudget(false)}>{editingBudgetId?"수정 저장":"임시 저장"}</button><button className="finance-primary" disabled={saving||!budgetTitle.trim()||!budgetFund||!budgetLines.some(x=>x.account_id&&Number(x.planned_amount)>0)} onClick={()=>void createBudget(true)}>{editingBudgetId?"수정 후 결재 요청":"저장 후 결재 요청"}</button></div></div>}
 <div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>{(englishUI?"Year":"연도")}</th><th>{(englishUI?"Budget proposal":"예산안")}</th><th>{(englishUI?"Fund":"기금")}</th><th>{(englishUI?"Total budget":"예산 총액")}</th><th>{(englishUI?"Status":"상태")}</th><th>{(englishUI?"Process":"처리")}</th></tr></thead><tbody>{budgets.map(b=><tr key={b.id}><td>{b.fiscal_year}</td><td>{b.title}</td><td>{fundName(funds.find(f=>f.id===b.fund_id))}</td><td>{money(budgetTotal(b))} MMK</td><td><span className={"finance-status "+b.status}>{status(b.status)}</span></td><td><div className="finance-actions">{["draft","rejected"].includes(b.status)&&<><button onClick={()=>editBudget(b)}>{(englishUI?"Edit":"수정")}</button><button onClick={()=>void deleteBudget(b)}>{(englishUI?"Delete":"삭제")}</button></>}{b.status==="draft"||b.status==="rejected"?<button disabled={saving} onClick={async()=>{if(!mutationsEnabled){setError((englishUI?"Finance changes are currently locked.":"재정 변경 기능은 현재 잠겨 있습니다."));return;}if(!supabase)return;setSaving(true);try{const r=await supabase.rpc("mrpst_submit_budget",{target_budget:b.id});if(r.error)throw r.error;const {data:verified,error:verifyError}=await supabase.from("finance_budgets").select("id,status").eq("id",b.id).maybeSingle();if(verifyError)throw verifyError;if(!verified||verified.id!==b.id||verified.status!=="submitted")throw new Error("예산 제출 상태를 확인할 수 없습니다.");setNotice((englishUI?"Budget submission status verified.":"예산 제출 상태를 확인했습니다."));await load();}catch(e:any){setError(e.message||"예산 제출을 확인할 수 없습니다.");}finally{setSaving(false);}}}>{(englishUI?"Submit":"제출")}</button>:null}{canApprove&&b.status==="submitted"&&<><button onClick={()=>void reviewBudget(b.id,true)}>{(englishUI?"Approve":"승인")}</button><button onClick={()=>void reviewBudget(b.id,false)}>{(englishUI?"Rejected":"반려")}</button></>}</div></td></tr>)}</tbody></table>{!loading&&!budgets.length&&<div className="empty-state"><strong>{(englishUI?"No budget proposals registered":"등록된 예산안이 없습니다")}</strong><span>{(englishUI?"Prepare budgets by fund.":"기금별 예산을 편성해 보세요.")}</span></div>}</div>
 <h4 className="finance-subheading">{(englishUI?"Budget vs actual":"예산 대비 집행 현황")}</h4><div className="finance-table-wrap"><table className="finance-table"><thead><tr><th>{(englishUI?"Year":"연도")}</th><th>{(englishUI?"Fund / account":"기금 / 계정")}</th><th>{(englishUI?"Budget":"예산")}</th><th>{(englishUI?"Spent":"집행")}</th><th>{(englishUI?"Balance":"잔액")}</th><th>{(englishUI?"Execution rate":"집행률")}</th></tr></thead><tbody>{actuals.map(x=>{const pct=Number(x.planned_amount)>0?Number(x.actual_amount)/Number(x.planned_amount)*100:0;return <tr key={x.budget_line_id}><td>{x.fiscal_year}</td><td>{((isMyanmar||isEnglish)?(x.fund_name_en||x.fund_name_ko):(x.fund_name_ko||x.fund_name_en))} · {((isMyanmar||isEnglish)?(x.account_name_en||x.account_name_ko):(x.account_name_ko||x.account_name_en))}</td><td>{money(Number(x.planned_amount))}</td><td>{money(Number(x.actual_amount))}</td><td>{money(Number(x.planned_amount)-Number(x.actual_amount))}</td><td>{pct.toFixed(1)}%</td></tr>;})}</tbody></table>{!actuals.length&&<div className="empty-state"><strong>{(englishUI?"No approved budgets":"승인된 예산이 없습니다")}</strong><span>{(englishUI?"Compare actual expenditure after budget approval.":"예산 승인 후 실제 집행액을 비교할 수 있습니다.")}</span></div>}</div></section>}
