 {showDonor&&<div className="finance-form"><h4>{editingDonorId?"후원자 정보 수정":"후원자 정보"}</h4><div className="finance-form-grid"><FormField label={(englishUI?"Donor / organization":"후원자 / 기관명")} className="wide"><input value={donorName} onChange={e=>setDonorName(e.target.value)} placeholder={(englishUI?"Individual, church or organization name":"개인, 교회 또는 기관명")}/></FormField><FormField label={(englishUI?"Category":"유형")}><select value={donorType} onChange={e=>setDonorType(e.target.value)}><option value="individual">{(englishUI?"Individual":"개인")}</option><option value="church">{(englishUI?"Church":"교회")}</option><option value="organization">{(englishUI?"Organization":"기관")}</option></select></FormField><FormField label={(englishUI?"Contact":"연락처")}><input value={donorPhone} onChange={e=>setDonorPhone(e.target.value)}/></FormField><FormField label={(englishUI?"Email":"이메일")}><input value={donorEmail} onChange={e=>setDonorEmail(e.target.value)}/></FormField><FormField label={(englishUI?"Country":"국가")}><input value={donorCountry} onChange={e=>setDonorCountry(e.target.value)}/></FormField></div><div className="finance-form-actions"><button onClick={()=>{setShowDonor(false);setEditingDonorId("");}}>{(englishUI?"Cancel":"취소")}</button><button className="finance-primary" disabled={saving||!donorName.trim()} onClick={()=>void createDonor()}>{editingDonorId?"정보 수정":"후원자 저장"}</button></div></div>}
